using DAL;
using Microsoft.Extensions.DependencyInjection;
using Model.DomainModel;
using Utils.Interface;
namespace Tests;
public class SellerFeedbackTests(ApiFactory f):ApiTest(f)
{
    [Fact]public async Task Seller_reviews_reports_reply_ownership_and_private_feedback()
    {
        var u=await LoginPhone("9882000001","Synthetic Feedback Seller");var sid=(await u.Post("/api/seller/register",new{display_name="Synthetic Feedback Store"})).Json["id"]!.GetValue<string>();var cat=Guid.NewGuid();await ApiFactory.DbExecAsync("INSERT INTO categories(id,name,slug,image_url,commission_bps,default_gst_bps,position,is_active,required_details)VALUES(@cat,'Synthetic Feedback','synthetic-feedback','',1000,500,0,1,'[]')",new{cat});
        var p=(await u.Post("/api/seller/products",new{category_id=cat,title="Synthetic Feedback Cotton Shirt",hsn_code="6205",gst_bps=500,variants=new[]{new{sku="FEEDBACK-SKU",mrp_paise=20000,price_paise=10000,stock=10}}})).Json;var pid=p["id"]!.GetValue<string>();var customer=await LoginPhone("9882000002","Synthetic Private Customer");var id=Guid.NewGuid();var second=Guid.NewGuid();
        foreach(var rid in new[]{id,second})await ApiFactory.DbExecAsync("INSERT INTO reviews(id,product_id,user_id,verified,rating,title,body,status,media,media_status,seller_reply,helpful_count,report_count)VALUES(@rid,@pid,@uid,1,@rating,'Soft shirt','Comfortable cotton shirt','published',@media,@ms,'',2,0)",new{rid,pid,uid=rid==id?customer.Id:u.Id,rating=rid==id?5:2,media=rid==id?"[{\"url\":\"/media/synthetic.webp\",\"kind\":\"image\"}]":"[]",ms=rid==id?"hidden":"published"});
        var r=await u.Get("/api/seller/reviews");Assert.True(r.Status==200,r.ToString());Assert.Equal(2,r.Json["total"]!.GetValue<long>());Assert.Equal(1,r.Json["distribution"]!["5"]!.GetValue<long>());Assert.Equal(1,r.Json["distribution"]!["2"]!.GetValue<long>());Assert.Equal(1,(await u.Get("/api/seller/reviews?rating=5&media=true&q=Soft")).Json["total"]!.GetValue<long>());Assert.Empty((await u.Get("/api/seller/reviews?rating=5")).Json["items"]![0]!["media"]!.AsArray());
        Assert.Equal(403,(await u.Put($"/api/seller/reviews/{id}/reply",new{reply="Thanks"})).Status);await ApiFactory.DbExecAsync("UPDATE sellers SET status='approved' WHERE id=@sid",new{sid});
        var other=await LoginPhone("9882000003");await other.Post("/api/seller/register",new{display_name="Synthetic Other Feedback"});await ApiFactory.DbExecAsync("UPDATE sellers SET status='approved' WHERE user_id=@uid",new{uid=other.Id});Assert.Empty((await other.Get("/api/seller/reviews")).Json["items"]!.AsArray());Assert.Equal(404,(await other.Put($"/api/seller/reviews/{id}/reply",new{reply="No"})).Status);
        var run=Guid.NewGuid();using var scope=Factory.Services.CreateScope();var ai=scope.ServiceProvider.GetRequiredService<AiDAL>();var db=scope.ServiceProvider.GetRequiredService<IMySqlDapperHelper>();await using(var tx=await db.BeginAsync()){await ai.InsertRunAsync(new(){Id=run,Task="review_reply",SellerId=Guid.Parse(sid),Inputs="{}",Output="{}",Status="draft",Mode="sandbox",CreatedAt=DateTime.UtcNow},tx);await tx.CommitAsync();}
        await ApiFactory.DbExecAsync("CREATE TRIGGER synthetic_feedback_fail BEFORE UPDATE ON ai_runs FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic AI finish rollback'");
        try{Assert.Equal(500,(await u.Put($"/api/seller/reviews/{id}/reply",new{reply="Must roll back",ai_run_id=run})).Status);Assert.Equal("",await ApiFactory.DbScalarAsync<string>("SELECT seller_reply FROM reviews WHERE id=@id",new{id}));Assert.Equal("draft",await ApiFactory.DbScalarAsync<string>("SELECT status FROM ai_runs WHERE id=@run",new{run}));}finally{await ApiFactory.DbExecAsync("DROP TRIGGER synthetic_feedback_fail");}
        r=await u.Put($"/api/seller/reviews/{id}/reply",new{reply="  Thanks for the feedback  ",ai_run_id=run});Assert.Equal(200,r.Status);Assert.Equal("Thanks for the feedback",await ApiFactory.DbScalarAsync<string>("SELECT seller_reply FROM reviews WHERE id=@id",new{id}));Assert.Equal("applied",await ApiFactory.DbScalarAsync<string>("SELECT status FROM ai_runs WHERE id=@run",new{run}));Assert.Equal(1,(await u.Get("/api/seller/reviews?unanswered=true")).Json["total"]!.GetValue<long>());
        r=await u.Post($"/api/seller/reviews/{id}/report",new{reason="spam",note="Synthetic report"});Assert.True(r.Status==200,r.ToString());Assert.False(r.Json["already"]!.GetValue<bool>());Assert.True((await u.Post($"/api/seller/reviews/{id}/report",new{reason="spam"})).Json["already"]!.GetValue<bool>());Assert.True((await u.Get("/api/seller/reviews?rating=5")).Json["items"]![0]!["reported"]!.GetValue<bool>());Assert.Equal(404,(await other.Post($"/api/seller/reviews/{id}/report",new{reason="spam"})).Status);
        var report=Guid.NewGuid();await ApiFactory.DbExecAsync("INSERT INTO product_reports(id,product_id,seller_id,user_id,reason,note,url,status,admin_note,seller_note)VALUES(@report,@pid,@sid,@uid,'wrong_price','Synthetic private feedback','https://example.test/synthetic','open','','')",new{report,pid,sid,uid=customer.Id});
        r=await u.Get("/api/seller/product-reports?status=open");Assert.Equal(1,r.Json["open"]!.GetValue<long>());Assert.Equal(1,r.Json["total"]!.GetValue<long>());Assert.Null(r.Json["items"]![0]!["user_id"]);Assert.Null(r.Json["items"]![0]!["customer"]);Assert.Empty((await other.Get("/api/seller/product-reports")).Json["items"]!.AsArray());Assert.Equal(404,(await other.Post($"/api/seller/product-reports/{report}/respond",new{note="No"})).Status);
        Assert.Equal(200,(await u.Post($"/api/seller/product-reports/{report}/respond",new{note="  Corrected listing  "})).Status);Assert.Equal("Corrected listing",await ApiFactory.DbScalarAsync<string>("SELECT seller_note FROM product_reports WHERE id=@report",new{report}));Assert.Equal(1,await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM audit_logs WHERE entity_id=@report AND action='product_report.seller_note'",new{report=report.ToString()}));Assert.Equal(422,(await u.Get("/api/seller/reviews?rating=6")).Status);Assert.Equal(422,(await u.Get("/api/seller/product-reports?status=unknown")).Status);Assert.Equal(422,(await u.Post($"/api/seller/product-reports/{report}/respond",new{note="x"})).Status);

        await scope.ServiceProvider.GetRequiredService<BAL.Interface.IReviewSettingsBAL>().UpdateAsync(new System.Text.Json.Nodes.JsonObject{["seller_can_report"]=false});Assert.Equal("reports_off",(await u.Post($"/api/seller/reviews/{second}/report",new{reason="spam"})).ErrorCode);
        Assert.Equal(422,(await u.Get("/api/seller/reviews?page=0")).Status);Assert.Equal(422,(await u.Put($"/api/seller/reviews/{id}/reply",new{})).Status);Assert.Equal(200,(await u.Put($"/api/seller/reviews/{id}/reply",new{reply=""})).Status);
    }
}
